    if (Math.random() < dt * 3) { var ep = D.g.localToWorld(new T.Vector3(-2.88, DEN_ROOM.y + 0.4, -1.25 + (Math.random() - 0.5) * 0.3)); this.puff(ep.x, ep.y, ep.z, 1, 'smoke', 0.02); }
