            var da = dd / 30 * Math.PI * 2, dx = Math.cos(da) * 2.6, dz = dz0 + Math.sin(da) * 1.4;
            var dash = P(this.geo.box, this.mat('dirt'), 0.36, 0.06, 0.24, dx, 0, dz); dash.rotation.y = -da;
            dash.position.y = this.localGround(G, dx, dz) + 0.03;
