      for (var w = 0; w < 18; w++) { var wx = 2.4 + (w * 0.37) % 2.4, wz = -2.2 + (w * 0.61) % 1.9; P(self.geo.ball, self.mat('flag', w % 5), 0.04, 0.04, 0.04, wx, at(wx, wz) + 0.12, wz); }
