      var pr = P(self.geo.gable, thatch, 0.75, 0.55, 0.75, 0, 1.08, hz + 1.2); pr.rotation.y = 0;
      P(self.geo.box, self.mat('holdRoof', 1), 1.25, 0.08, 0.16, 0, 1.1, hz + 1.6);
