      var g = D.list[name], body = g.group, t = now / 1000 + k * 1.7;
      if (chase) {
        g.wait = 0; g.mood = 'zoom'; g.speed = 3.4; g.target = null;
        g.tx = chase.x + (k - 1) * 0.5; g.tz = chase.z;
        if (now > (g.barkAt || 0)) { g.barkAt = now + 1200 + Math.random() * 1800; self.bark(name, true); }
      }
