    this.part(fish, this.geo.cone4, this.mat('salmon', 1), 0.1, 0.18, 0.08, 0, 0, -0.25).rotation.x = -Math.PI / 2;
    var a = Math.random() * Math.PI * 2, dx = Math.cos(a), dz = Math.sin(a);
