      m.position.set(mx + (Math.random() - 0.5) * 0.5 + dx * Math.random() * 0.3, groundY(mx, mz) + 0.02, mz + (Math.random() - 0.5) * 0.5 + dz * Math.random() * 0.3);
      m.rotation.y = Math.random() * 6;
