      var c = C[i];
      if (!c.down || c.t < 0.3) continue;
      var mx = c.x + Math.sin(c.dir + c.g.rotation.y) * 0.5, mz = c.z + Math.cos(c.dir + c.g.rotation.y) * 0.5;
